468: /* 校验完整大端配置块，持久化、应用并回读；失败执行回滚。 */
469: bms_afe_hw_error_t bms_afe_hw_profile_commit_be(const u8 *pdata, u16 qty)
470: {
471:     bms_afe_hw_profile_t before;
472:     bms_afe_hw_profile_t candidate;
473:     bms_afe_hw_profile_t verify;
474:     bms_afe_hw_profile_t effective;
475:     u16 i;
476: 
477:     if (!bms_afe_hw_access_is_active())
478:     {
479:         s_afe_hw_last_error = BMS_AFE_HW_ERROR_AUTH;
480:         return BMS_AFE_HW_ERROR_AUTH;
481:     }
482:     if (pdata == 0 || qty != BMS_AFE_HW_PROFILE_WORD_COUNT)
483:     {
484:         s_afe_hw_last_error = BMS_AFE_HW_ERROR_VALIDATION;
485:         return BMS_AFE_HW_ERROR_VALIDATION;
486:     }
487:     if (!bms_afe_hw_profile_get(&before))
488:     {
489:         s_afe_hw_last_error = BMS_AFE_HW_ERROR_STORE;
490:         return (bms_afe_hw_error_t)s_afe_hw_last_error;
491:     }
492: 
493:     candidate = before;
494:     for (i = 0u; i < qty; ++i)
495:         ((u16 *)&candidate)[i] = afe_hw_profile_word_be(&pdata[(u32)i * 2u]);
496: 
497:     if (!bms_afe_hw_profile_validate(&candidate))
498:     {
499:         s_afe_hw_last_error = BMS_AFE_HW_ERROR_VALIDATION;
500:         return BMS_AFE_HW_ERROR_VALIDATION;
501:     }
502: 
503:     if (!bms_afe_hw_profile_set(&candidate))
504:     {
505:         s_afe_hw_apply_state = BMS_AFE_HW_APPLY_IDLE;
506:         s_afe_hw_last_error = BMS_AFE_HW_ERROR_STORE;
507:         return (bms_afe_hw_error_t)s_afe_hw_last_error;
508:     }
509: 
510:     if (!bms_afe_apply_protection_config())
511:     {
512:         s_afe_hw_last_error = BMS_AFE_HW_ERROR_APPLY_VERIFY;
513:         return afe_hw_profile_rollback(&before);
514:     }
515: 
516:     if (!bms_afe_hw_profile_get(&verify) ||
517:         !afe_hw_profile_words_equal(&candidate, &verify) ||
518:         !bms_afe_hw_profile_get_effective(&effective))
519:     {
520:         s_afe_hw_last_error = BMS_AFE_HW_ERROR_APPLY_VERIFY;
521:         return afe_hw_profile_rollback(&before);
522:     }
523: 
524:     s_afe_hw_apply_state = BMS_AFE_HW_APPLY_OK;
525:     s_afe_hw_last_error = BMS_AFE_HW_ERROR_NONE;
526:     bms_afe_hw_access_close();
527:     return BMS_AFE_HW_ERROR_NONE;
528: }

