202: /* 通过安全门禁采样并更新恢复资格及输出授权。 */
203: void bms_afe_sample(void)
204: {
205:     bms_afe_aux_measurements_t m;
206: 
207:     if (s_guard.test_shutdown_hold || service_failsafe_wait()) return;
208: 
209:     /* 新样本确认恢复资格期间，保留真正已发生的通信故障。 */
210:     if (bms_error_get(BMS_ERROR_AFE1)) s_guard.comm_fault_latched = 1u;
211:     AFE_SAMPLE();
212:     memset(&m, 0, sizeof(m));
213:     if (!AFE_AUX(&m))
214:     {
215: #if BMS_AFE_BACKEND == BMS_AFE_BACKEND_SH3673510
216:         if (sh3673510_bms_afe_sample_pending()) return;
217: #endif
218:         note_invalid();
219:         return;
220:     }
221: 
222:     s_guard.comm_failures = 0u;
223: #if BMS_AFE_BACKEND == BMS_AFE_BACKEND_SH3673510
224:     if (!sh3673510_bms_afe_sample_pending())
225: #endif
226:     {
227:         if (s_guard.valid_snapshot_streak < BMS_AFE_VALID_SNAPSHOT_RELEASE_COUNT)
228:             ++s_guard.valid_snapshot_streak;
229:     }
230: 
231:     if (s_guard.valid_snapshot_streak >= BMS_AFE_VALID_SNAPSHOT_RELEASE_COUNT)
232:     {
233:         s_guard.comm_inhibit = 0u;
234:         s_guard.comm_fault_latched = 0u;
235:     }
236:     else if (s_guard.comm_fault_latched)
