242:     /*
243:      * 资格尚未确认不是采样失败。
244:      * comm_inhibit 时调用功能服务会令快照读取失败并锁存虚假断线疑似，
245:      * 导致健康启动后两个 FET 长期关闭。
246:      */
247:     if (!s_guard.comm_inhibit) bms_features_service();
248:     if (!apply_requested()) note_invalid();

